//----- (800B45D4) --------------------------------------------------------
// Dolphin SDK C_MTXLookAt: Builds view basis from camera-target, up cross backward, computesnegative
// dot products for translation
void C_MTXLookAt(float m[3][4], const float *camPos, const float *camUp, const float *target)
{
  float v7; // [sp+18h] [-38h] BYREF
  float v8; // [sp+1Ch] [-34h]
  float v9; // [sp+20h] [-30h]
  float v10; // [sp+24h] [-2Ch] BYREF
  float v11; // [sp+28h] [-28h]
  float v12; // [sp+2Ch] [-24h]
  float v13; // [sp+30h] [-20h] BYREF
  float v14; // [sp+34h] [-1Ch]
  float v15; // [sp+38h] [-18h]

  v13 = *camPos - *target;
  v14 = camPos[1] - target[1];
  v15 = camPos[2] - target[2];
  PSVECNormalize(&v13, &v13);
  PSVECCrossProduct(camUp, &v13, &v10);
  PSVECNormalize(&v10, &v10);
  PSVECCrossProduct(&v13, &v10, &v7);
  (*m)[0] = v10;
  (*m)[1] = v11;
  (*m)[2] = v12;
  (*m)[3] = -(float)((float)(camPos[2] * v12) + (float)((float)(*camPos * v10) + (float)(camPos[1] * v11)));
  (*m)[4] = v7;
  (*m)[5] = v8;
  (*m)[6] = v9;
  (*m)[7] = -(float)((float)(camPos[2] * v9) + (float)((float)(*camPos * v7) + (float)(camPos[1] * v8)));
  (*m)[8] = v13;
  (*m)[9] = v14;
  (*m)[10] = v15;
  (*m)[11] = -(float)((float)(camPos[2] * v15) + (float)((float)(*camPos * v13) + (float)(camPos[1] * v14)));
}

//----- (800B4760) --------------------------------------------------------
// Dolphin SDK C_MTXLightFrustum: Builds 3x4 light-projection frustum includingS/T texture scale
