//----- (8010FD9C) --------------------------------------------------------
// Returns whether nonnull sprite has visibility flag 2
int GSmenu_IsSpriteVisible(const MenuSprite *sprite)
{
  return sprite != nullptr && (sprite->flags & 2) != 0;
}

//----- (8010FDC8) --------------------------------------------------------
// Sets or clears sprite visibility flag 2 and returns sprite pointer
void *GSmenu_SetSpriteVisible(MenuSprite *sprite, unsigned __int8 visible)
{
  unsigned __int8 v2; // r0

  if ( sprite != nullptr )
  {
    if ( visible != 0 )
      v2 = sprite->flags | 2;
    else
      v2 = sprite->flags & 0xFD;
    sprite->flags = v2;
  }
  return sprite;
}

//----- (8010FE04) --------------------------------------------------------
// Frees linked sprite slots by clearing flags, then clears chain head
void GSmenu_ClearSpriteChain(MenuSprite **head)
{
  MenuSprite **link; // r5

  if ( head != nullptr )
  {
    for ( link = head; *link != nullptr; link = (MenuSprite **)*link )
      (*link)->flags = 0;
    *head = nullptr;
  }
}

//----- (8010FE38) --------------------------------------------------------
// Allocates among 500 120-byte sprites, initializes flags 7/unit scale/opaque white and appends to
// chain; logs pool exhaustion
MenuSprite *winSpriteAdd(MenuSprite **head)
{
  MenuSprite *sprite; // r31
  int remainingSlots; // ctr
  MenuSprite **tailLink; // r3

  if ( head == nullptr )
    return nullptr;
  sprite = (MenuSprite *)unk_80525630;
  remainingSlots = 500;
  while ( sprite->flags != 0 )
  {
    ++sprite;
    if ( --remainingSlots == 0 )
    {
      GSlog_WriteNoOp("Error!! winSpriteAdd() [\x83X\x83v\x83\x89\x83C\x83g\x83\x8F\x81[\x83N\x95s\x91\xAB]\n");
      return nullptr;
    }
  }
  memset(sprite, 0, sizeof(MenuSprite));
  sprite->flags = 7;
  tailLink = head;
  sprite->scaleX = 1.0;
  sprite->scaleY = 1.0;
  sprite->color = 0xFFFFFFFF;
  while ( *tailLink != nullptr )
    tailLink = (MenuSprite **)*tailLink;
  *tailLink = sprite;
  return sprite;
}

//----- (8010FF00) --------------------------------------------------------
// Allocates and zeroes 60000-byte sprite pool
void *GSmenu_InitSpritePool()
{
  void *pool; // r3

  pool = GSmemAlloc(0xEA60u);
  unk_80525630 = pool;
  if ( pool != nullptr )
    return memset(pool, 0, 0xEA60u);
  return pool;
}

//----- (8010FF44) --------------------------------------------------------
// Selects sprite render layer from menu class and layer selector, defaulting to layer 7
int GSmenu_GetSpriteLayer(MenuWork *menu, const MenuSprite *sprite)
{
  MenuDefinition *MenuDefinitionClamped; // r31
  int result; // r3

  MenuDefinitionClamped = getMenuDefinitionClamped(menu->menuId);
  if ( menu->renderLayer == getMenuResourceHandle() )
    return getMenuResourceHandle();
  if ( MenuDefinitionClamped->flags >> 5 == 3 )
  {
    result = getMenuResourceHandle();
    if ( menu->renderLayer != result )
      menu->renderLayer = result;
  }
  else if ( sprite->layerSelector != 0 )
  {
    return getMenuRenderLayerId();
  }
  else
  {
    return 7;
  }
  return result;
}

