//----- (80145540) --------------------------------------------------------
// HP and unsupported stat attributes are unchanged; 0x88..0x8C select Attack, Defense, SpAtk, SpDef,
// Speed; scales with integer numerator/denominator, returns zero for absent multiplier, skips division
// when denominator is zero
unsigned __int16 applyNatureBonusToStat(
        unsigned __int8 natureIndex,
        unsigned __int16 statAttribute,
        unsigned __int16 stat)
{
  int unmodifiedStat; // r29
  const XDNatureRecord *nature; // r3
  int scaledStat; // r3
  unsigned __int8 multiplierIndex; // r3
  const XDNatureMultiplier *selectedMultiplier; // r3
  const XDNatureMultiplier *multiplier; // r30
  unsigned __int8 numerator; // r31
  int denominator; // r0

  unmodifiedStat = stat;
  nature = getNatureRecord(natureIndex);
  if ( nature == nullptr )
  {
    LOWORD(scaledStat) = unmodifiedStat;
    return scaledStat;
  }
  if ( statAttribute == 138 )
  {
    multiplierIndex = getNatureSpecialAttackMultiplierIndex(nature);
  }
  else if ( statAttribute >= 0x8Au )
  {
    if ( statAttribute == 140 )
    {
      multiplierIndex = getNatureSpeedMultiplierIndex(nature);
    }
    else
    {
      if ( statAttribute >= 0x8Cu )
      {
LABEL_15:
        LOWORD(scaledStat) = unmodifiedStat;
        return scaledStat;
      }
      multiplierIndex = getNatureSpecialDefenseMultiplierIndex(nature);
    }
  }
  else if ( statAttribute == 136 )
  {
    multiplierIndex = getNatureAttackMultiplierIndex(nature);
  }
  else
  {
    if ( statAttribute < 0x88u )
      goto LABEL_15;
    multiplierIndex = getNatureDefenseMultiplierIndex(nature);
  }
  selectedMultiplier = getNatureMultiplier(multiplierIndex);
  multiplier = selectedMultiplier;
  if ( selectedMultiplier != nullptr )
  {
    numerator = getNatureMultiplierNumerator(selectedMultiplier);
    denominator = getNatureMultiplierDenominator(multiplier);
    scaledStat = unmodifiedStat * numerator;
    if ( denominator != 0 )
      scaledStat /= denominator;
  }
  else
  {
    LOWORD(scaledStat) = 0;
  }
  return scaledStat;
}

