//----- (80145680) --------------------------------------------------------
// Updates level and all six stats; internal species 0x12F has max HP 1; preserves fainting when
// current HP is zero and old max HP is nonzero, otherwise adjusts current HP by the max-HP delta
// through the clamping setter
void updateAllPkmStatsFromLevel(XDPokemonRecord *pokemon, unsigned __int8 level)
{
  unsigned __int16 species; // r30
  unsigned __int16 oldMaxHp; // r31
  unsigned __int16 newMaxHp; // r29
  unsigned __int16 currentHp; // r3
  unsigned __int16 adjustedHp; // r4

  species = getPkmSpecies(pokemon);
  oldMaxHp = call_getPkmHPStat_safe(pokemon);
  setPkmLevel(pokemon, level);
  if ( species == 303 )
  {
    newMaxHp = 1;
    call_setPkmHPStat_safe(pokemon, 1u);
  }
  else
  {
    newMaxHp = updatePkmStat(pokemon, level, 0x87u, 3u, 0x93u, 0x8Du, level + 10);
  }
  updatePkmStat(pokemon, level, 0x88u, 4u, 0x94u, 0x8Eu, 5u);
  updatePkmStat(pokemon, level, 0x89u, 5u, 0x95u, 0x8Fu, 5u);
  updatePkmStat(pokemon, level, 0x8Cu, 8u, 0x98u, 0x92u, 5u);
  updatePkmStat(pokemon, level, 0x8Au, 6u, 0x96u, 0x90u, 5u);
  updatePkmStat(pokemon, level, 0x8Bu, 7u, 0x97u, 0x91u, 5u);
  currentHp = getPkmCurrentHP(pokemon);
  if ( currentHp != 0 || oldMaxHp == 0 )
  {
    adjustedHp = 1;
    if ( species != 303 )
      adjustedHp = currentHp + newMaxHp - oldMaxHp;
    setPkmCurrentHP(pokemon, adjustedHp);
  }
}

//----- (801457F0) --------------------------------------------------------
// Reads species base stat, IV and EV by attribute IDs, calculates the stat, applies PID nature and
// writes the chosen stat attribute
unsigned __int16 updatePkmStat(
        XDPokemonRecord *pokemon,
        unsigned __int8 level,
        unsigned __int16 statAttribute,
        unsigned __int16 baseStatAttribute,
        unsigned __int16 ivAttribute,
        unsigned __int16 evAttribute,
        unsigned int increment)
{
  unsigned __int16 species; // r31
  unsigned __int8 natureIndex; // r29
  unsigned __int16 baseStat; // r31
  unsigned __int16 effortValue; // r3
  unsigned __int16 statBeforeNature; // r3
  unsigned __int32 scaledStat; // r3
  unsigned __int16 updatedStat; // r31

  species = getPkmSpecies(pokemon);
  natureIndex = getPkmNature(pokemon);
  baseStat = getPkmOrSpeciesAttribute(nullptr, species, baseStatAttribute, 0);
  LOBYTE(ivAttribute) = getPkmOrSpeciesAttribute(pokemon, 0, ivAttribute, 0);
  effortValue = getPkmOrSpeciesAttribute(pokemon, 0, evAttribute, 0);
  statBeforeNature = calcStatWithoutNatureBonus(baseStat, ivAttribute, effortValue, level, increment);
  scaledStat = applyNatureBonusToStat(natureIndex, statAttribute, statBeforeNature);
  updatedStat = scaledStat;
  setPkmAttribute((unsigned __int8 *)pokemon, 0, statAttribute, 0, scaledStat);
  return updatedStat;
}

//----- (801458D4) --------------------------------------------------------
// Computes low16((2*baseStat + IV + floor(EV/4))*level/100 + increment); inputs are narrowed
// explicitly and this helper does not validate level or IV/EV limits
unsigned __int16 calcStatWithoutNatureBonus(
        unsigned __int16 baseStat,
        unsigned __int8 individualValue,
        unsigned __int16 effortValue,
        unsigned __int8 level,
        unsigned int increment)
{
  return increment + level * (individualValue + 2 * baseStat + (effortValue >> 2)) / 100;
}

