// Derives level from species growth type and stored experience; this wrapper has no explicit null
// check
unsigned __int8 calculatePkmLevelFromExperience(XDPokemonRecord *pokemon)
{
  XDPokemonRecord *pokemonOrGrowthType; // r31
  unsigned __int16 species; // r3
  unsigned __int8 growthType; // r0
  XDPokemonRecord *sourcePokemon; // r3
  unsigned int experience; // r3

  pokemonOrGrowthType = pokemon;
  species = getPkmSpecies(pokemon);
  growthType = getSpeciesExpGrowthType(species);
  sourcePokemon = pokemonOrGrowthType;
  LOBYTE(pokemonOrGrowthType) = growthType;
  experience = getPkmEXP(sourcePokemon);
  return calculateLevelFromExperience((unsigned __int8)pokemonOrGrowthType, experience);
}

//----- (80145954) --------------------------------------------------------
// Scans thresholds for levels 1 through 100; returns previous level on the first larger threshold,
// zero for invalid growth type or EXP below level-1 threshold
unsigned __int8 calculateLevelFromExperience(unsigned __int8 growthType, unsigned int experience)
{
  const unsigned int *thresholds; // r30
  int candidateLevel; // r31

  thresholds = getExperienceGrowthTable(growthType);
  if ( thresholds == nullptr )
    return 0;
  for ( candidateLevel = 1; candidateLevel < 101; ++candidateLevel )
  {
    if ( getExperienceAtLevel(thresholds, candidateLevel) > experience )
      break;
  }
  return candidateLevel - 1;
}

//----- (801459BC) --------------------------------------------------------
// Selects the growth table then returns its level threshold; zero for invalid growth type or level >=
// 101
unsigned int calculateExperienceForLevel(unsigned __int8 growthType, unsigned __int8 level)
{
  const unsigned int *thresholds; // r3

  thresholds = getExperienceGrowthTable(growthType);
  if ( thresholds != nullptr )
    return getExperienceAtLevel(thresholds, level);
  else
    return 0;
}

