//----- (80146E78) --------------------------------------------------------
// Clamps PP-Ups to three, suppresses write for selected nonzero/non-355 move with base PP <=4; return
// is r3 residue retained conservatively
int setPkmMovePPUps(XDPokemonRecord *pokemon, unsigned __int16 selector, unsigned __int8 ppUps)
{
  int result; // r3
  int v7; // r31
  unsigned __int16 PkmMoveId; // r3
  XDMoveDefinition *MoveDefinition; // r3

  result = (int)getPkmMoveSlot(pokemon, selector);
  v7 = result;
  if ( result != 0 )
  {
    if ( ppUps > 3u )
      ppUps = 3;
    result = hasPkmMove(pokemon, selector);
    if ( (unsigned __int8)result != 1
      || (PkmMoveId = getPkmMoveId(pokemon, selector),
          MoveDefinition = getMoveDefinition(PkmMoveId),
          (unsigned __int8)(result = moveDefinitionGetBasePP(MoveDefinition)) > 4u) )
    {
      *(_BYTE *)(v7 + 3) = ppUps;
    }
  }
  return result;
}

//----- (80146F04) --------------------------------------------------------
// Clamps current PP to stored-slot maximum then writes resolved slot; return is r3 residue retained
// conservatively
int setPkmMovePP(XDPokemonRecord *pokemon, unsigned __int16 selector, unsigned __int8 currentPp)
{
  int result; // r3
  int v7; // r31

  result = (int)getPkmMoveSlot(pokemon, selector);
  v7 = result;
  if ( result != 0 )
  {
    result = getPkmMoveMaxPP(pokemon, selector);
    if ( (unsigned __int8)result < (unsigned int)currentPp )
      currentPp = result;
    *(_BYTE *)(v7 + 2) = currentPp;
  }
  return result;
}

