//----- (801486E4) --------------------------------------------------------
// Selectors 0..3 resolve effective moves; 4..7 address stored slots 0..3; r5 is unused in this build;
// effective shadow and locked slots can point to shared writable records
XDMoveSlot *getPkmMoveSlot(XDPokemonRecord *pokemon, unsigned __int16 selector)
{
  unsigned int purificationState; // r0
  char remainingNormalSlots; // r25
  unsigned __int8 slotIndex; // r24
  unsigned __int16 shadowPokemonId; // r3
  unsigned __int16 selectedShadowPokemonId; // r3
  int referenceMoveId; // r3
  unsigned __int8 normalSlotUnlocked[4]; // [sp+8h] [-28h]

  *(_DWORD *)normalSlotUnlocked = 0;
  if ( pokemon == nullptr )
    return nullptr;
  purificationState = (unsigned __int8)getPkmPurifAdvState(pokemon);
  if ( purificationState < 5 )
  {
    if ( purificationState < 4 )
      remainingNormalSlots = purificationState >= 2;
    else
      remainingNormalSlots = 2;
  }
  else
  {
    remainingNormalSlots = 3;
  }
  for ( slotIndex = 0; slotIndex < 4u; ++slotIndex )
  {
    normalSlotUnlocked[slotIndex] = 0;
    shadowPokemonId = getPkmShadowPkmID_safe(pokemon);
    if ( getShadowPkmReferenceMoveId(shadowPokemonId, slotIndex) < 0x163u && remainingNormalSlots != 0 )
    {
      normalSlotUnlocked[slotIndex] = 1;
      --remainingNormalSlots;
    }
  }
  if ( selector < 4u )
  {
    if ( isPkmShadow(pokemon) == 1 )
    {
      selectedShadowPokemonId = getPkmShadowPkmID_safe(pokemon);
      referenceMoveId = getShadowPkmReferenceMoveId(selectedShadowPokemonId, selector);
      if ( referenceMoveId > 355 && referenceMoveId < 374 )
        return &gShadowMoveSlots[referenceMoveId - 356];
      if ( normalSlotUnlocked[selector] == 0 )
        return &gLockedMoveSlot;
    }
  }
  else
  {
    selector -= 4;
    if ( selector >= 4u )
      return nullptr;
  }
  return &pokemon->moves[selector];
}

