//----- (80148E98) --------------------------------------------------------
// Clears one condition (or all when conditionId is 0) on the combatant's move context.
int clearCombatantCondition(Combatant *combatant, unsigned __int16 conditionId)
{
  MoveContext *CombatantMoveEffectState; // r3
  MoveContext *owner; // r31

  if ( combatant != nullptr )
  {
    CombatantMoveEffectState = (MoveContext *)getCombatantMoveEffectState(combatant);
    owner = CombatantMoveEffectState;
    if ( conditionId != 0 )
    {
      combatant = (Combatant *)battleMoveContextConditionHas(CombatantMoveEffectState, conditionId);
      if ( (unsigned __int8)combatant == 1 )
        return battleMoveContextConditionClear(owner, conditionId);
    }
    else
    {
      return battleMoveContextClearConditions((MoveExecution *)CombatantMoveEffectState);
    }
  }
  return (int)combatant;
}

//----- (80148F00) --------------------------------------------------------
// Resets a condition's source to 0 when its replacement decision is 2 (replaceable).
int resetCombatantConditionSourceIfReplaceable(Combatant *combatant, unsigned __int16 conditionId)
{
  MoveContext *CombatantMoveEffectState; // r31

  if ( combatant != nullptr )
  {
    CombatantMoveEffectState = (MoveContext *)getCombatantMoveEffectState(combatant);
    combatant = (Combatant *)battleMoveContextConditionReplacementDecision(CombatantMoveEffectState, conditionId);
    if ( (unsigned __int8)combatant == 2 )
      return battleMoveContextConditionSetSource(CombatantMoveEffectState, conditionId, 0);
  }
  return (int)combatant;
}

