//----- (80149BA8) --------------------------------------------------------
// Null-checked PP-Up setter with clamp to three and base-PP exclusion; return is r3 residue retained
// conservatively
int setPkmMovePPUps_safe(XDPokemonRecord *pokemon, unsigned __int16 selector, unsigned __int8 ppUps)
{
  XDPokemonRecord *pokemonRecord; // r28
  XDMoveSlot *moveSlot; // r31
  unsigned __int16 moveId; // r3
  XDMoveDefinition *moveDefinition; // r3

  pokemonRecord = pokemon;
  if ( pokemon != nullptr )
  {
    pokemon = (XDPokemonRecord *)getPkmMoveSlot(pokemon, selector);
    moveSlot = (XDMoveSlot *)pokemon;
    if ( pokemon != nullptr )
    {
      if ( ppUps > 3u )
        ppUps = 3;
      pokemon = (XDPokemonRecord *)hasPkmMove(pokemonRecord, selector);
      if ( (unsigned __int8)pokemon != 1
        || (moveId = getPkmMoveId(pokemonRecord, selector),
            moveDefinition = getMoveDefinition(moveId),
            (unsigned __int8)(pokemon = (XDPokemonRecord *)moveDefinitionGetBasePP(moveDefinition)) > 4u) )
      {
        moveSlot->ppUps = ppUps;
      }
    }
  }
  return (int)pokemon;
}

//----- (80149C38) --------------------------------------------------------
// Null-checked PP setter; clamp uses stored maximum while destination follows selector; return is r3
// residue retained conservatively
int setPkmMovePP_safe(XDPokemonRecord *pokemon, unsigned __int16 selector, unsigned __int8 currentPp)
{
  XDPokemonRecord *pokemonRecord; // r28
  XDMoveSlot *moveSlot; // r31

  pokemonRecord = pokemon;
  if ( pokemon != nullptr )
  {
    pokemon = (XDPokemonRecord *)getPkmMoveSlot(pokemon, selector);
    moveSlot = (XDMoveSlot *)pokemon;
    if ( pokemon != nullptr )
    {
      pokemon = (XDPokemonRecord *)getPkmMoveMaxPP(pokemonRecord, selector);
      if ( (unsigned __int8)pokemon < (unsigned int)currentPp )
        currentPp = (unsigned __int8)pokemon;
      moveSlot->currentPp = currentPp;
    }
  }
  return (int)pokemon;
}

