//----- (8014A7DC) --------------------------------------------------------
// Tests one of eight pairing flag bits in byte +188 of the record: slot 0..3 selects the bit pair
// (0x40/0x10/0x04/0x01, doubled when highBits==1). Used by AI combo partner selection.
int __fastcall getPkmMovePairFlag(int pokemon, unsigned __int8 slot, char highBits)
{
  if ( pokemon == 0 )
    return 0;
  if ( highBits == 1 )
  {
    if ( slot == 2 )
    {
      return (*(_BYTE *)(pokemon + 188) & 8) != 0;
    }
    else if ( slot >= 2u )
    {
      return slot < 4u && (*(_BYTE *)(pokemon + 188) & 2) != 0;
    }
    else if ( slot != 0 )
    {
      return (*(_BYTE *)(pokemon + 188) & 0x20) != 0;
    }
    else
    {
      return (*(_BYTE *)(pokemon + 188) & 0x80) != 0;
    }
  }
  else if ( highBits != 0 )
  {
    return 0;
  }
  else if ( slot == 2 )
  {
    return (*(_BYTE *)(pokemon + 188) & 4) != 0;
  }
  else if ( slot >= 2u )
  {
    if ( slot >= 4u )
      return 0;
    else
      return *(_BYTE *)(pokemon + 188) & 1;
  }
  else if ( slot != 0 )
  {
    return (*(_BYTE *)(pokemon + 188) & 0x10) != 0;
  }
  else
  {
    return (*(_BYTE *)(pokemon + 188) & 0x40) != 0;
  }
}

