//----- (8014CAA4) --------------------------------------------------------
// Marks reveal presentation as shown for ordinary move slots1..3 using moveIndex0..2; byte+1
// masks0x04/0x08/0x10; out-of-range index is ignored
ShadowPokemon *setShadowOrdinaryMoveRevealShown(
        ShadowPokemon *shadowRecord,
        unsigned __int8 moveIndex,
        unsigned __int8 shown)
{
  unsigned int packedFlags; // r5
  int revealedMoveMask; // r0

  if ( moveIndex < 3u )
  {
    if ( shown != 0 )
    {
      packedFlags = shadowRecord->packedFlags[1];
      revealedMoveMask = (packedFlags >> 2) & 7 | (1 << moveIndex);
    }
    else
    {
      packedFlags = shadowRecord->packedFlags[1];
      revealedMoveMask = (packedFlags >> 2) & 7 & ~(1 << moveIndex);
    }
    shadowRecord->packedFlags[1] = (4 * revealedMoveMask) & 0x1C | packedFlags & 0xE3;
  }
  return shadowRecord;
}

//----- (8014CAF8) --------------------------------------------------------
// Tests whether reveal presentation was shown for ordinary move slot moveIndex+1; accepts indices0..2
// only and otherwise returnsfalse
bool hasShadowOrdinaryMoveRevealBeenShown(ShadowPokemon *shadowRecord, unsigned __int8 moveIndex)
{
  return moveIndex < 3u && ((shadowRecord->packedFlags[1] >> 2) & 7 & (1 << moveIndex)) != 0;
}

