//----- (8014DEBC) --------------------------------------------------------
// Returns the number of valid Pokemon in the trainer's six party slots.
unsigned __int16 __fastcall countValidPartyPkm(void *trainerBlockAddress)
{
  unsigned __int16 partySlot; // r31
  unsigned __int16 validCount; // r30
  XDPokemonRecord *PartyPokemonSlotSafe; // r3

  partySlot = 0;
  validCount = 0;
  while ( partySlot < 6u )
  {
    PartyPokemonSlotSafe = getPartyPokemonSlotSafe(trainerBlockAddress, partySlot);
    if ( isPkmValid(PartyPokemonSlotSafe) )
      ++validCount;
    ++partySlot;
  }
  return validCount;
}

//----- (8014DF38) --------------------------------------------------------
// Returns the first empty party slot index, or -1 if all six are filled.
int __fastcall scriptGetFirstInvalidPartyPkmIndex(void *trainerBlockAddress)
{
  int i; // r31
  XDPokemonRecord *PartyPokemonSlotSafe; // r30

  for ( i = 0; i < 6; ++i )
  {
    PartyPokemonSlotSafe = getPartyPokemonSlotSafe(trainerBlockAddress, i);
    if ( !isPkmValid(PartyPokemonSlotSafe) )
      return i;
    getPkmPurifCtr_safe(PartyPokemonSlotSafe);
  }
  return -1;
}

//----- (8014DFB0) --------------------------------------------------------
// Returns the number of valid party Pokemon that are not fainted.
int __fastcall scriptCountNotFaintedPartyPkm(void *trainerBlockAddress)
{
  int partySlot; // r31
  int count; // r29
  XDPokemonRecord *PartyPokemonSlotSafe; // r30

  partySlot = 0;
  count = 0;
  do
  {
    PartyPokemonSlotSafe = getPartyPokemonSlotSafe(trainerBlockAddress, partySlot);
    if ( isPkmValid(PartyPokemonSlotSafe) && getPkmOrSpeciesAttribute(PartyPokemonSlotSafe, 0, 0x7Bu, 0) == 0 )
      ++count;
    ++partySlot;
  }
  while ( partySlot < 6 );
  return count;
}

//----- (8014E044) --------------------------------------------------------
// Subtracts coupons from the trainer's current balance (field 0xD); a non-positive
// amount also updates field 0xE.
void subtractTrainerCoupons(TrainerSave *trainer, int amount)
{
  int coupons; // r3
  int totalCoupons; // r3

  coupons = getPlayerDataField(trainer, 0xDu, 0);
  setPartyDataField(trainer, 0xDu, coupons - amount);
  if ( amount <= 0 )
  {
    totalCoupons = getPlayerDataField(trainer, 0xEu, 0);
    setPartyDataField(trainer, 0xEu, totalCoupons - amount);
  }
}

//----- (8014E0BC) --------------------------------------------------------
// Adds coupons to the trainer's balance (field 0xD); a non-negative amount also adds to
// the lifetime total (field 0xE).
