  setPkmHappiness(&pokemon, context->happiness);
  setPkmLocationCaught((unsigned __int8 *)&pokemon, context->metLocation);
  setPkmLevelMet((unsigned __int8 *)&pokemon, context->level);
  setPkmBallCaughtWith((unsigned __int8 *)&pokemon, 4u);
  setPkmOTGender((unsigned __int8 *)&pokemon, context->otGender);
  setPkmSIDTID(&pokemon, context->trainerId);
  setPkmOTName((unsigned __int8 *)&pokemon, (unsigned __int16 *)context->otName);
  nickname = (unsigned __int16 *)context->nickname;
  if ( nickname != nullptr )
    setPkmName((unsigned __int8 *)&pokemon, nickname);
  setPkmEXP(&pokemon, context->experience);
