//----- (801555B4) --------------------------------------------------------
// Sets message variables 77/87 to viable trainer names and selects target wording by kind, trainer
// count, side, and mode
// Kind 11 with owner: one trainer IDs 4FE5/4FE8/4FEA, two trainers IDs 4FE6/4FE9/4FEB for mode
// 0/1/other
// Other path: first side IDs 4F6A/4F6C/4F68, second side IDs 4F69/4F6B/4F67
// Exact localized phrases are absent from the live registered RAM archives; the complete ID mapping is
// documented
const unsigned __int16 *selectBattleTargetMessageText(int battlerIndex, unsigned __int8 messageMode)
{
  unsigned __int8 battleSideAttribute; // r30
  Side *side; // r29
  unsigned __int16 viableTrainerCount; // r26
  Trainer *owningTrainer; // r28
  unsigned __int16 trainerIndex; // r25
  Trainer *trainer; // r3
  Trainer *viableTrainer; // r27
  unsigned int firstNameId; // r3
  unsigned int secondNameId; // r3
  unsigned int ownerNameId; // r3

  battleSideAttribute = battleGetAttribute(nullptr, 0, 0x14u, 0);
  side = (Side *)battleResolveObject(2u, (void *)battlerIndex);
  viableTrainerCount = 0;
  owningTrainer = (Trainer *)battleFindOwningTrainerForCombatant(0, (Combatant *)battlerIndex);
  for ( trainerIndex = 0; trainerIndex < 2u; ++trainerIndex )
  {
    trainer = battleGetUsableTrainer(side, trainerIndex);
    viableTrainer = trainer;
    if ( trainer != nullptr && (unsigned __int8)battleTrainerHasViableParty(trainer) != 0 )
    {
      if ( viableTrainerCount != 0 )
      {
        if ( viableTrainerCount == 1 )
        {
          secondNameId = battleTrainerGetName(viableTrainer);
          msgSetVar(87, secondNameId);
        }
      }
      else
      {
        firstNameId = battleTrainerGetName(viableTrainer);
        msgSetVar(77, firstNameId);
      }
      ++viableTrainerCount;
    }
  }
  if ( battleIsKind11(nullptr) && owningTrainer != nullptr )
  {
    if ( viableTrainerCount > 1u )
    {
      if ( messageMode != 0 )
      {
        if ( messageMode == 1 )
          return GSmsg_GetString(0x4FE9u);
        else
          return GSmsg_GetString(0x4FEBu);
      }
      else
      {
        return GSmsg_GetString(0x4FE6u);
      }
    }
    else
    {
      ownerNameId = battleTrainerGetName(owningTrainer);
      msgSetVar(77, ownerNameId);
      if ( messageMode != 0 )
      {
        if ( messageMode == 1 )
          return GSmsg_GetString(0x4FE8u);
        else
          return GSmsg_GetString(0x4FEAu);
      }
      else
      {
        return GSmsg_GetString(0x4FE5u);
      }
    }
  }
  else if ( battleObjectIsOnFirstSide((void *)battlerIndex, battleSideAttribute) )
  {
    if ( messageMode != 0 )
    {
      if ( messageMode == 1 )
        return GSmsg_GetString(0x4F6Cu);
      else
        return GSmsg_GetString(0x4F68u);
    }
    else
    {
      return GSmsg_GetString(0x4F6Au);
    }
  }
  else if ( messageMode != 0 )
  {
    if ( messageMode == 1 )
      return GSmsg_GetString(0x4F6Bu);
    else
      return GSmsg_GetString(0x4F67u);
  }
  else
  {
    return GSmsg_GetString(0x4F69u);
  }
}

