//----- (801BAE1C) --------------------------------------------------------
// For durationTicks frames, restarts controller-1 rumble and yields; returns 0.
int __fastcall scriptTimedRumbleTask(
        char rumbleMode,
        unsigned __int8 strength,
        unsigned int durationTicks,
        unsigned __int8 decay,
        char enabled)
{
  unsigned int framesLeft; // r31

  framesLeft = durationTicks;
  if ( enabled == 0 )
    return 0;
  while ( framesLeft != 0 )
  {
    GSinput_StartRumble(1u, rumbleMode, strength, durationTicks, decay);
    GSthreadYield();
    --framesLeft;
  }
  return 0;
}

