  Definition = battleGetDefinition(GlobalBattleId);
  PartyData = (const PartyBlock *)getPartyData();
  if ( getSavedRespawnFloorId(PartyData) == 0 )
    return 0;
  if ( (unsigned __int8)battleDefinitionRestoreFloorOnLoss(Definition) == 0 )
    return 0;
  GlobalResult = battleGetGlobalResult();
  if ( (unsigned __int8)battleResultIsOpponentLoss(0, GlobalResult) == 1 )
    return 0;
