//----- (801F3838) --------------------------------------------------------
// Decides a timed-out battle: compares surviving Pokemon counts, then HP percentages, of the
// two sides and records the result.
int __fastcall battleResolveResultBySurvivingCountAndHp(Context *context)
{
  int result; // r3
  unsigned __int16 TrainersPerSide; // r25
  unsigned __int16 PartySlotsPerTrainer; // r24
  Side *side; // r26
  unsigned __int16 playerViableCount; // r28
  int playerHp; // r29
  unsigned int playerHpPercent; // r26
  Side *opponentSide; // r27
  unsigned __int16 opponentViableCount; // r29
  int opponentHp; // r30
  unsigned int opponentHpPercent; // r27

  result = battleGetGlobalResult();
  if ( (unsigned __int16)result != 1 )
  {
    TrainersPerSide = (unsigned __int8)battleGetTrainersPerSide(context);
    PartySlotsPerTrainer = (unsigned __int8)battleGetPartySlotsPerTrainer(context);
    side = (Side *)battleResolveObject(4u, nullptr);
    playerViableCount = battleSideCountViablePartyPokemon(side, TrainersPerSide, PartySlotsPerTrainer);
    playerHp = battleSideSumCurrentHp(side, TrainersPerSide, PartySlotsPerTrainer);
    playerHpPercent = 100 * playerHp / (unsigned int)battleSideSumMaximumHp(side, TrainersPerSide, PartySlotsPerTrainer);
    opponentSide = (Side *)battleResolveObject(5u, nullptr);
    opponentViableCount = battleSideCountViablePartyPokemon(opponentSide, TrainersPerSide, PartySlotsPerTrainer);
    opponentHp = battleSideSumCurrentHp(opponentSide, TrainersPerSide, PartySlotsPerTrainer);
    opponentHpPercent = 100
                      * opponentHp
                      / (unsigned int)battleSideSumMaximumHp(opponentSide, TrainersPerSide, PartySlotsPerTrainer);
    battleMergeResult(context, 0);
    if ( playerViableCount > (unsigned int)opponentViableCount )
      battleMergeResult(context, 2u);
    if ( playerViableCount < (unsigned int)opponentViableCount )
      battleMergeResult(context, 3u);
    result = battleGetGlobalResult();
    if ( (_WORD)result == 0 )
    {
      if ( playerHpPercent >= opponentHpPercent )
        result = battleMergeResult(context, 2u);
      if ( playerHpPercent <= opponentHpPercent )
        return battleMergeResult(context, 3u);
    }
  }
  return result;
}

