    return 0;
  shadowTagHolder = battleFindCombatantWithAbility(context, 0x17u, 0, 2u, (int)combatant);
  arenaTrapHolder = battleFindCombatantWithAbility(context, 0x47u, 0, 2u, (int)combatant);
  magnetPullHolder = battleFindCombatantWithAbility(context, 0x2Au, 0, 0, (int)combatant);
