//----- (801F5FC0) --------------------------------------------------------
// Returns 1 if first acts before second: compares move priority (when useActionPriority), then
// effective speed, breaking ties randomly.
int battleCombatantActsBefore(Context *context, Combatant *first, Combatant *second, unsigned __int8 useActionPriority)
{
  unsigned __int8 Weather; // r30
  bool applyTrainerBonus; // r31
  unsigned __int16 FirstAttackRnd; // r28
  TrainerSave *OwningTrainerSaveData; // r3
  unsigned int EffectiveSpeed; // r29
  TrainerSave *trainerSave; // r3
  unsigned int secondSpeed; // r30
  unsigned __int16 SelectedMoveId; // r28
  unsigned __int16 moveId; // r27
  char MovePriority; // r31
  char secondPriority; // r3

  if ( first == nullptr || second == nullptr )
    return 1;
  Weather = battleGetWeather(context, 1);
  applyTrainerBonus = fightFloor_GetFightKindDoBadgeCheckFlag(context);
  FirstAttackRnd = fightFloor_GetFirstAttackRnd(context);
  OwningTrainerSaveData = battleFindOwningTrainerSaveData((int)context, (int)first);
  EffectiveSpeed = battleCombatantGetEffectiveSpeed(
                     first,
                     applyTrainerBonus,
                     Weather,
                     FirstAttackRnd,
                     OwningTrainerSaveData);
  trainerSave = battleFindOwningTrainerSaveData((int)context, (int)second);
  secondSpeed = battleCombatantGetEffectiveSpeed(second, applyTrainerBonus, Weather, FirstAttackRnd, trainerSave);
  if ( useActionPriority != 0 )
  {
    SelectedMoveId = battleCombatantGetSelectedMoveId(first);
    moveId = battleCombatantGetSelectedMoveId(second);
  }
  else
  {
    SelectedMoveId = 0;
    moveId = 0;
  }
  MovePriority = getMovePriority(SelectedMoveId);
  secondPriority = getMovePriority(moveId);
  if ( MovePriority != 0 || secondPriority != 0 )
  {
    if ( MovePriority > secondPriority )
      return 1;
    if ( MovePriority < secondPriority )
      return 0;
  }
  if ( EffectiveSpeed > secondSpeed )
    return 1;
  if ( EffectiveSpeed >= secondSpeed )
    return (HSD_Rand() & 1) != 0;
  return 0;
}

