//----- (801F6290) --------------------------------------------------------
// Returns the active weather (0 none, 1..5) from field conditions 0x4E..; when
// checkWeatherSuppression, Cloud Nine / Air Lock (abilities 13, 77) force 0.
int __fastcall battleGetWeather(Context *context, char checkWeatherSuppression)
{
  if ( checkWeatherSuppression == 1 )
  {
    if ( (unsigned __int16)battleCountCombatantsWithAbility(context, 0xDu, 0, 0) != 0 )
      return 0;
    if ( (unsigned __int16)battleCountCombatantsWithAbility(context, 0x4Du, 0, 0) != 0 )
      return 0;
  }
  if ( fightFloor_GetIsJoutaiDataId(context, 0x4Eu) )
    return 0;
  if ( fightFloor_GetIsJoutaiDataId(context, 0x4Fu) )
    return 1;
  if ( fightFloor_GetIsJoutaiDataId(context, 0x50u) )
    return 2;
  if ( fightFloor_GetIsJoutaiDataId(context, 0x51u) )
    return 3;
  if ( fightFloor_GetIsJoutaiDataId(context, 0x52u) )
    return 5;
  if ( fightFloor_GetIsJoutaiDataId(context, 0x53u) )
    return 4;
  if ( fightFloor_GetIsJoutaiDataId(context, 0x54u) )
    return 1;
  if ( fightFloor_GetIsJoutaiDataId(context, 0x55u) )
    return 2;
  return !fightFloor_GetIsJoutaiDataId(context, 0x56u) ? 0 : 3;
}

