// Fills outList with active combatants filtered by requireCanAct and relationMode relative to
// referenceCombatant. Returns the count.
int __fastcall battleCollectCombatants(
        Context *context,
        Combatant **outList,
        char requireCanAct,
        char relationMode,
        Combatant *referenceCombatant)
{
  int count; // r24
  unsigned __int8 formatIndex; // r23
  unsigned int trainersPerSide; // r26
  unsigned int activeSlotsPerTrainer; // r25
  Side *referenceSide; // r30
  unsigned __int16 i; // r27
  Side *usableSide; // r3
  Side *side; // r31
  unsigned __int16 j; // r29
  Trainer *trainer; // r23
  unsigned __int16 k; // r28
  Combatant *activeCombatant; // r3
  Combatant *candidate; // r17

  battleClearCombatantPointerList((int)outList);
  count = 0;
  formatIndex = battleGetFormatIndex(context);
  trainersPerSide = (unsigned __int8)battleGetTrainersPerSide(context);
  activeSlotsPerTrainer = (unsigned __int8)battleGetActiveSlotsPerTrainer(context);
  if ( relationMode != 0 )
  {
    if ( (unsigned __int8)battleCombatantIsValid(referenceCombatant) == 0 )
      return 0;
    referenceSide = (Side *)battleResolveObjectForFormat(2u, referenceCombatant, formatIndex);
  }
  else
  {
    referenceSide = nullptr;
  }
  for ( i = 0; i < 2u; ++i )
  {
    usableSide = battleGetUsableSide(context, i);
    side = usableSide;
    if ( usableSide == nullptr )
      continue;
    if ( relationMode == 1 )
    {
      if ( referenceSide != usableSide )
        continue;
    }
    else if ( relationMode == 2 && referenceSide == usableSide )
    {
      continue;
    }
    for ( j = 0; j < trainersPerSide; ++j )
    {
      trainer = battleGetUsableTrainer(side, j);
      if ( trainer != nullptr )
      {
        for ( k = 0; k < activeSlotsPerTrainer; ++k )
        {
          activeCombatant = battleTrainerGetUsableActiveCombatant(trainer, k);
          candidate = activeCombatant;
          if ( activeCombatant != nullptr
            && (requireCanAct != 1 || (unsigned __int8)battleCombatantCanAct(activeCombatant) != 0)
            && (relationMode != 3 || candidate != referenceCombatant)
            && (battleAppendCombatantPointer((int)outList, (int)candidate) & 0x8000u) == 0 )
          {
            ++count;
          }
        }
      }
    }
  }
  return count;
}

