  XDPokemonRecord *PartyPokemonSlotSafe; // r3
  unsigned __int8 PkmLevel; // r3
  unsigned __int16 *playerName; // r3
  unsigned __int16 *trainerName; // r3
  Definition *definition; // r3
  unsigned __int8 slot; // r26
  unsigned __int16 index; // r27
  unsigned __int16 itemId; // r25
  unsigned __int8 quantity; // r3
  unsigned __int8 SexDataId; // r25
  unsigned __int16 Name; // r3
  const unsigned __int16 *String; // r3
  unsigned __int8 j; // r26
