// Plays the trainer's Poke Ball throw (hokaku) effect for itemId, using an auxiliary actor
// when required; phase selects start/finish.
void __fastcall fightTrainerHokakuThrowEffect(Trainer *trainer, unsigned __int16 itemId, char phase)
{
  Actor *actor; // r31
  unsigned __int16 Resource14ByItemId; // r3
  unsigned __int16 sequenceId; // r30
  char useAuxActor; // r29
  unsigned __int16 Resource18ByItemId; // r3
  Sequence *RegisteredActorSequence; // r31
  Sequence *sequence; // r3
  Sequence *startSequence; // r3
  Sequence *waitSequence; // r31
  Sequence *endSequence; // r3
  Vec angles; // [sp+8h] [-28h] BYREF
  Vec coordinates; // [sp+14h] [-1Ch] BYREF

  actor = (Actor *)battleTrainerGetActor(trainer);
  if ( actor != nullptr )
  {
    if ( (unsigned __int8)battleGetKind(nullptr) == 12 || (unsigned __int8)battleGetKind(nullptr) == 13 )
    {
      Resource14ByItemId = XDItemAnimation_GetResource14ByItemId(itemId);
      *((_DWORD *)&gLensFlareInitialized + 6) = actor;
      sequenceId = Resource14ByItemId;
      useAuxActor = 0;
    }
    else
    {
      Resource18ByItemId = XDItemAnimation_GetResource18ByItemId(itemId);
      useAuxActor = 1;
      sequenceId = Resource18ByItemId;
    }
    if ( phase != 0 )
    {
      switch ( phase )
      {
        case 1:
          if ( useAuxActor != 0 )
          {
            battleGridCaptureTemporaryVisibility();
            getRegisteredSequenceActorCoordinates(actor, &coordinates);
            getRegisteredSequenceActorAngles(actor, &angles);
            setRegisteredSequenceActorCoordinates(*((Actor **)&gLensFlareInitialized + 6), &coordinates);
            setRegisteredSequenceActorAngles(*((Actor **)&gLensFlareInitialized + 6), &angles);
            setRegisteredSequenceActorVisible(actor, false);
            battleGridCaptureVisibility();
            setRegisteredSequenceActorVisible(*((Actor **)&gLensFlareInitialized + 6), true);
          }
          RegisteredActorSequence = findRegisteredActorSequence(*((Actor **)&gLensFlareInitialized + 6), sequenceId, 4u);
          startRegisteredBattleSequence(RegisteredActorSequence, true);
          while ( isBattleSequenceActiveUnpaused(RegisteredActorSequence) )
            GSthreadYield();
          break;
        case 2:
          sequence = findRegisteredActorSequence(*((Actor **)&gLensFlareInitialized + 6), sequenceId, 4u);
          destroyRegisteredBattleSequence(sequence);
          if ( useAuxActor != 0 )
          {
            setRegisteredSequenceActorVisible(*((Actor **)&gLensFlareInitialized + 6), false);
            deleteRegisteredSequenceActor(*((Actor **)&gLensFlareInitialized + 6));
            setRegisteredSequenceActorVisible(actor, true);
          }
          break;
        case 3:
          createBattleSequence(actor, 0x57u, 4u, 0);
          break;
        case 4:
          startSequence = findRegisteredActorSequence(actor, 0x57u, 4u);
          startRegisteredBattleSequence(startSequence, true);
          break;
        case 5:
          waitSequence = findRegisteredActorSequence(actor, 0x57u, 4u);
          while ( isBattleSequenceActiveUnpaused(waitSequence) )
            GSthreadYield();
          break;
        case 6:
          endSequence = findRegisteredActorSequence(actor, 0x57u, 4u);
          destroyRegisteredBattleSequence(endSequence);
          break;
        default:
          break;
      }
    }
    else
    {
      if ( useAuxActor != 0 )
        *((_DWORD *)&gLensFlareInitialized + 6) = createSequenceAuxiliaryActorWrapper(0x42u);
      createBattleSequence(*((Actor **)&gLensFlareInitialized + 6), sequenceId, 4u, 0);
    }
  }
}

