//----- (802010A8) --------------------------------------------------------
// Sets the AI role (part) record's move-type adjustment byte for moveType (< 14).
int __fastcall fightTrainerPokemonPartDB_SetWazaTypeRevise(
        unsigned __int16 partDataId,
        unsigned __int8 moveType,
        char value)
{
  int result; // r3

  result = fightTrainerPokemonPartDataBiosGetPtr(partDataId);
  if ( result != 0 && moveType < 0xEu )
  {
    result += moveType;
    *(_BYTE *)(result + 8) = value;
  }
  return result;
}

//----- (802010F4) --------------------------------------------------------
// Returns the AI role (part) record's move-type adjustment byte for moveType (< 14).
int __fastcall fightTrainerPokemonPartDB_GetWazaTypeRevise(unsigned __int16 partDataId, unsigned __int8 moveType)
{
  int Ptr; // r3

  Ptr = fightTrainerPokemonPartDataBiosGetPtr(partDataId);
  if ( Ptr == 0 )
    return 0;
  if ( moveType < 0xEu )
    return *(unsigned __int8 *)(Ptr + moveType + 8);
  return 0;
}

