  xDPokemonRecord = battlePartyRecordGetPokemon(partyRecord);
  pokemon = xDPokemonRecord;
  if ( xDPokemonRecord != nullptr )
  {
    fillPkmProgressGaugeSummary(xDPokemonRecord, (int)outStatus);
    outStatus[40] = XDMenuGetDisplayedPokemonGender(pokemon);
  }
  outStatus[22] = 1;
  if ( battleCombatantIsPlayerOwned(combatant) )
    outStatus[22] = 0;
  result = fightFloor_GetFightKindPokemonStatusMenuSubbarFlag(nullptr);
  if ( !result )
    outStatus[22] = 1;
  outStatus[45] = 0;
