//----- (80209DF8) --------------------------------------------------------
// Returns the opponent-history entry (of count) for opponent, or null.
OpponentHistory *battleFindOpponentHistory(OpponentHistory *history, unsigned __int16 count, Combatant *opponent)
{
  unsigned int countLimit; // r31
  unsigned __int16 i; // r29

  if ( history == nullptr )
    return nullptr;
  countLimit = count;
  for ( i = 0; i < countLimit; ++i )
  {
    if ( (unsigned __int8)battleOpponentHistoryIsValid(&history[i]) != 0
      && (Combatant *)battleOpponentHistoryGetCombatant(&history[i]) == opponent )
    {
      return &history[i];
    }
  }
  return nullptr;
}

//----- (80209E84) --------------------------------------------------------
// Returns whether an opponent-history entry references a combatant.
int battleOpponentHistoryIsValid(OpponentHistory *history)
{
  return battleOpponentHistoryGetCombatant(history) != 0;
}

//----- (80209EAC) --------------------------------------------------------
// Initializes an opponent-history entry for opponent, recording its current HP.
void battleInitializeOpponentHistory(OpponentHistory *history, Combatant *opponent)
{
  XDPokemonRecord *Pokemon; // r3
  unsigned __int16 PkmCurrentHP; // r3

  if ( history != nullptr && opponent != nullptr )
  {
    battleResetOpponentHistoryEntry(history);
    battleOpponentHistorySetCombatant(history, (int)opponent);
    Pokemon = battleCombatantGetPokemon(opponent);
    PkmCurrentHP = getPkmCurrentHP(Pokemon);
    battleOpponentHistorySetInitialHp(history, PkmCurrentHP);
  }
}

//----- (80209F10) --------------------------------------------------------
// Resets count opponent-history entries.
void battleResetOpponentHistoryArray(OpponentHistory *history, unsigned __int16 count)
{
  unsigned int countLimit; // r31
  unsigned __int16 i; // r30

  if ( history != nullptr )
  {
    countLimit = count;
    for ( i = 0; i < countLimit; ++i )
      battleResetOpponentHistoryEntry(&history[i]);
  }
}

//----- (80209F68) --------------------------------------------------------
// Clears an opponent-history entry (combatant, move, initial HP, damage).
void battleResetOpponentHistoryEntry(OpponentHistory *history)
{
  battleOpponentHistorySetCombatant(history, 0);
  battleOpponentHistorySetMoveId(history, 0);
  battleOpponentHistorySetInitialHp(history, 0);
  battleOpponentHistorySetDamage(history, 0);
}

