//----- (80233A68) --------------------------------------------------------
// Clears the four local trainers' original and entry hero blocks and releases all their party
// Pokémon.
void toolentryTaisenInit()
{
  signed int i; // r31
  TrainerSave *heroSave; // r3
  signed int j; // r30
  XDPokemonRecord *pokemon; // r3
  signed int k; // r31
  TrainerSave *entryHeroSave; // r3
  signed int m; // r30
  XDPokemonRecord *entryPokemon; // r3

  for ( i = 0; i < 4; ++i )
  {
    heroSave = (TrainerSave *)toolentryTaisenGetHeroPtr(i);
    resetTrainerSaveBlock(heroSave);
    for ( j = 0; j < 6; ++j )
    {
      pokemon = toolentryTaisenGetPokemonPtr(i, j);
      releasePokemon(pokemon);
    }
  }
  for ( k = 0; k < 4; ++k )
  {
    entryHeroSave = (TrainerSave *)battleEntryGetSelectedHeroInternal(k);
    resetTrainerSaveBlock(entryHeroSave);
    for ( m = 0; m < 6; ++m )
    {
      entryPokemon = toolentryTaisenGetEntryPokemonPtr(k, m);
      releasePokemon(entryPokemon);
    }
  }
}

