  species = getPkmSpeciesIndex3(pokemon);
  entry_count = block->count;
  for ( entry_index = 0; entry_index < entry_count; ++entry_index )
  {
    if ( (block->entries[entry_index].species_and_flags & 0x3FFF) == species )
      return;
  }
  block->entries[entry_count].species_and_flags = species | 0x8000;
