// RE region24-27: scriptThreadCanResume
// Resume gate waits for a selected context clock to reach sleepDeadline and/or a byte synchronization
// flag to satisfy mode1 (< expected) or mode2 (== expected); clears fulfilled wait conditions
// PAL entry equals public GXXE01 checkSleepEnd__Q28GSscript10TigaThreadFv (0x8023e82c) + 0x1F3C; exact
// IDA extent versus source size 0x118
unsigned __int8 scriptThreadCanResume(TigaThread *thread)
{
  int sync_mode; // r0
  unsigned __int8 equalModeFlagValue; // r0
  unsigned __int8 lessModeFlagValue; // r4

  if ( (thread->state_flags & 4) != 0 )
  {
    if ( thread->owner->timers[thread->wait_timer_index] < (double)thread->timer_threshold )
      return 0;
    thread->state_flags &= ~4u;
  }
  sync_mode = thread->sync_mode;
  if ( thread->sync_mode != 0 )
  {
    if ( sync_mode == 2 )
    {
      if ( thread->sync_flag >= 0x10u )
        equalModeFlagValue = 0;
      else
        equalModeFlagValue = thread->owner->sync_flags[thread->sync_flag];
      if ( thread->sync_value != equalModeFlagValue )
        return 0;
    }
    else if ( sync_mode == 1 )
    {
      lessModeFlagValue = thread->sync_flag >= 0x10u ? 0 : thread->owner->sync_flags[thread->sync_flag];
      if ( lessModeFlagValue >= (int)thread->sync_value )
        return 0;
    }
    thread->sync_mode = 0;
  }
  return 1;
}

//----- (80240880) --------------------------------------------------------
// RE region24-27: scriptThreadResetExecution
// Clear execution/register state, initialize downward-growing variant/return stacks, install type53
// null return sentinel, clear stack depth and tail counters
// PAL entry equals public GXXE01 initTiga__Q28GSscript10TigaThreadFv (0x8023e944) + 0x1F3C; exact IDA
// extent versus source size 0xAC
void scriptThreadResetExecution(TigaThread *thread)
{
  memset(&thread->instruction_pointer, 0, 0x144u);
  thread->stack = &thread->stack_allocation[thread->stack_count];
  thread->return_stack = &thread->return_stack_allocation[thread->return_stack_count];
  thread->stack_base = thread->stack_allocation;
  thread->return_stack_base = thread->return_stack_allocation;
  --thread->stack;
  thread->stack->type = ptr;
  thread->stack->value.asInt = 0;
  thread->frame = thread->stack;
  thread->source_line = 0;
  thread->state_flags = 0;
  thread->group = 0;
  thread->host_thread = nullptr;
}

//----- (8024092C) --------------------------------------------------------
// RE region24-27: scriptThreadAllocateStacks
// Free old stack ownership, allocate variantCount*8 and returnAddressCount*4 buffers, store capacities
// PAL entry equals public GXXE01 setStackArea__Q28GSscript10TigaThreadFii (0x8023e9f0) + 0x1F3C; exact
// IDA extent versus source size 0x64
void scriptThreadAllocateStacks(TigaThread *thread, unsigned int variantCount, unsigned int returnAddressCount)
{
  scriptThreadFreeOwnedData(thread);
  thread->stack_allocation = (GSscriptVar *)GSoperatorNewArray(8 * variantCount);
  thread->return_stack_allocation = (unsigned int *)GSoperatorNewArray(4 * returnAddressCount);
  thread->stack_count = variantCount;
  thread->return_stack_count = returnAddressCount;
}

