//----- (80283D38) --------------------------------------------------------
// Sets a layer TEV stage's texcoord, texture map and color channel (255 = none) and marks it dirty.
void GSgfxLayer_SetTevMapping(
        Layer *layer,
        unsigned __int8 stage,
        unsigned __int8 texcoord,
        unsigned __int8 textureMap,
        unsigned __int8 channel)
{
  Layer *texcoordValue; // r8
  Layer **stageBase; // r5
  int stageBit; // r4

  texcoordValue = (Layer *)texcoord;
  stageBase = &layer->next + 3 * stage;
  stageBase[940] = texcoordValue;
  stageBase[941] = (Layer *)textureMap;
  if ( channel == 255 )
    stageBase[942] = (Layer *)255;
  else
    stageBase[942] = (Layer *)(channel + 4);
  stageBit = 1 << stage;
  layer->renderCaches[0].dirtyGroups[9] |= stageBit;
  layer->renderCaches[0].dirtyCategories |= 8u;
  layer->renderCaches[1].dirtyGroups[9] |= stageBit;
  layer->renderCaches[1].dirtyCategories |= 8u;
}

//----- (80283DB4) --------------------------------------------------------
// Binds texture to a layer texture slot in both render caches when it changed or is dirty.
void GSgfxLayer_SelectTexture(Layer *layer, unsigned __int8 slot, Texture *texture)
{
  int slotIndex; // r7
  char *slotBase; // r6

  slotIndex = slot;
  slotBase = (char *)layer + slotIndex * 4;
  if ( layer->renderCaches[0].textures[slotIndex] != texture
    || *((Texture **)slotBase + 1534) != texture
    || texture->dirty != 0 )
  {
    *((_DWORD *)slotBase + 1488) = texture;
    layer->renderCaches[0].dirtyTextures |= 1 << slot;
    layer->renderCaches[1].textures[slotIndex] = texture;
    layer->renderCaches[1].dirtyTextures |= 1 << slot;
  }
}

