//----- (80289E00) --------------------------------------------------------
// Flips the shape renderer's double buffer and executes the frees deferred for that buffer.
void GsShapeRender_SwapBuffers(ShapeRenderer *render)
{
  render->currentBuffer = render->currentBuffer == 0;
  GsShapeRender_ExecuteDeferredFrees(render);
}

