//----- (802BA464) --------------------------------------------------------
// Selects a layer pass and copies the EFB into texture (see GSgfxLayerEffectTextureCopy).
void GSgfxLayerTextureCopy(
        Layer *layer,
        unsigned int pass,
        Texture *texture,
        unsigned __int8 verticalFilter,
        unsigned __int8 *filter,
        unsigned __int8 colorUpdate,
        unsigned __int8 alphaUpdate,
        unsigned __int8 depthUpdate)
{
  if ( layer->selectedPass != pass )
  {
    layer->selectedPass = pass;
    layer->currentFifo = &layer->fifos[layer->selectedPass];
  }
  GSgfxLayerEffectTextureCopy(layer, texture, verticalFilter, filter, colorUpdate, alphaUpdate, depthUpdate);
}

