//----- (802C7F08) --------------------------------------------------------
// AI: decides whether target can switch out, considering Shadow Tag, Arena Trap and Magnet Pull
// holders, Flying type/Levitate and Steel type exemptions and trapping conditions 22/14/37; outputs
// the trapping holder.
int battleAICheckFightFloorCheckFightActionCombatantSwitchSelect(
        Trainer *observer,
        Context *context,
        Combatant *target,
        int *outTrapHolder)
{
  char canIgnoreGroundTrap; // r28
  char steelType; // r27
  Combatant *shadowTagHolder; // r29
  Combatant *arenaTrapHolder; // r30
  Combatant *magnetPullHolder; // r31

  canIgnoreGroundTrap = 0;
  steelType = 0;
  if ( (unsigned __int8)battleCombatantIsValid(target) == 0 )
    return 0;
  shadowTagHolder = battleAIGetFightFloorCombatantPtrAryPokemonAbilityIdFirst(observer, context, 0x17u, 0, 2u, target);
  arenaTrapHolder = battleAIGetFightFloorCombatantPtrAryPokemonAbilityIdFirst(observer, context, 0x47u, 0, 2u, target);
  magnetPullHolder = battleAIGetFightFloorCombatantPtrAryPokemonAbilityIdFirst(observer, context, 0x2Au, 0, 0, target);
  if ( (unsigned __int8)battleAIIsCombatantTypeId(observer, target, 2u) == 1
    || (unsigned __int8)battleAIIsCombatantAbilityId(observer, target, 0x1Au) == 1 )
  {
    canIgnoreGroundTrap = 1;
  }
  if ( (unsigned __int8)battleAIIsCombatantTypeId(observer, target, 8u) == 1 )
    steelType = 1;
  if ( (unsigned __int8)battleAIIsCombatantConditionId(observer, target, 22) == 1
    || (unsigned __int8)battleAIIsCombatantConditionId(observer, target, 14) == 1
    || (unsigned __int8)battleAIIsCombatantConditionId(observer, target, 37) == 1 )
  {
    return 1;
  }
  if ( shadowTagHolder != nullptr )
  {
    if ( outTrapHolder != nullptr )
      *outTrapHolder = (int)shadowTagHolder;
    return 2;
  }
  else if ( arenaTrapHolder == nullptr || canIgnoreGroundTrap != 0 )
  {
    if ( magnetPullHolder != nullptr && steelType == 1 )
    {
      if ( outTrapHolder != nullptr )
        *outTrapHolder = (int)magnetPullHolder;
      return 2;
    }
    else
    {
      return 0;
    }
  }
  else
  {
    if ( outTrapHolder != nullptr )
      *outTrapHolder = (int)arenaTrapHolder;
    return 2;
  }
}

