//----- (802C8138) --------------------------------------------------------
// battleForEachCombatant callback for the ability search; stores the match and returns 0 to stop.
unsigned __int8 battleAIGetFightFloorCombatantPtrAryPokemonAbilityIdFirstSub(
        Combatant *combatant,
        unsigned __int8 iteration,
        AIFindAbility *query)
{
  Combatant *reference; // r30
  Trainer *observer; // r29
  void *referenceSide; // r28
  unsigned int sideFilter; // r0
  void *combatantSide; // r3
  unsigned int sideFilter2; // r0

  reference = query->reference;
  observer = query->observer;
  if ( (unsigned __int8)battleCombatantCanAct(combatant) == 0 )
    return 1;
  if ( reference != nullptr )
  {
    sideFilter = query->sideFilter;
    if ( sideFilter == 1 )
    {
      referenceSide = battleResolveObject(2u, reference);
    }
    else if ( sideFilter == 2 )
    {
      referenceSide = battleResolveObject(3u, reference);
    }
    else
    {
      referenceSide = nullptr;
    }
  }
  else
  {
    referenceSide = nullptr;
  }
  combatantSide = battleResolveObject(2u, combatant);
  sideFilter2 = query->sideFilter;
  if ( (sideFilter2 == 1 || sideFilter2 == 2) && referenceSide == nullptr )
    return 1;
  if ( sideFilter2 != 0 )
  {
    if ( sideFilter2 != 1 && sideFilter2 != 2 )
      return 1;
    if ( referenceSide != combatantSide )
      return 1;
  }
  else if ( reference != nullptr && reference == combatant )
  {
    return 1;
  }
  if ( (unsigned __int8)battleAIIsCombatantAbilityId(observer, combatant, query->ability) != 1 )
    return 1;
  query->found = combatant;
  return 0;
}

