//----- (802CA6BC) --------------------------------------------------------
// Finds maximal signed32-bit score with initial floor-200, gathers at most16 tied input indices,
// chooses first or HSD_Rand modulo tie count according to randomTies==1
// Tie count starts0 and is checked before division; count0 or all scores<-200 returns-1, allzero
// scores are valid ties
// Caller scores revised through AIAddValue stay[-200,200], so the floor normally includes every
// nonempty candidate set
int battleAIChooseMaximumSignedScoreIndex(int *scores, unsigned __int16 count, unsigned __int8 randomTies)
{
  int maximumScore; // r9
  unsigned __int16 clearIndex; // r8
  unsigned __int16 tieCount; // r31
  int clearSlot; // r0
  unsigned __int16 i; // r7
  unsigned int inputCount; // r0
  unsigned __int16 j; // r8
  int tieSlot; // r4
  unsigned __int16 selectedTieIndex; // r0
  int tiedIndices[16]; // [sp+8h] [-48h]

  maximumScore = -200;
  clearIndex = 0;
  tieCount = 0;
  while ( clearIndex < 0x10u )
  {
    clearSlot = clearIndex++;
    tiedIndices[clearSlot] = -1;
  }
  for ( i = 0; i < (unsigned int)count; ++i )
  {
    if ( maximumScore < scores[i] )
      maximumScore = scores[i];
  }
  inputCount = count;
  for ( j = 0; j < inputCount; ++j )
  {
    if ( maximumScore <= scores[j] )
    {
      tieSlot = tieCount++;
      tiedIndices[tieSlot] = j;
    }
    if ( tieCount >= 0x10u )
      break;
  }
  if ( tieCount == 0 )
    return -1;
  if ( tieCount == 1 )
  {
    selectedTieIndex = 0;
  }
  else if ( randomTies == 1 )
  {
    selectedTieIndex = (unsigned __int16)HSD_Rand() % (int)tieCount;
  }
  else
  {
    selectedTieIndex = 0;
  }
  return tiedIndices[selectedTieIndex];
}

