//----- (802CA868) --------------------------------------------------------
// Adds delta scaled by (percent - 50) / 50 to score, clamped to +/-200.
int battleAIReviseValue(int score, unsigned __int8 percent, int delta)
{
  return battleAIAddValue(score, (__int16)(((__int16)(100 * percent / 100) - 50) * delta / 50));
}

//----- (802CA8B0) --------------------------------------------------------
// Returns score + delta clamped to [-200, 200].
int battleAIAddValue(int score, int delta)
{
  if ( delta <= 0 )
  {
    if ( delta < 0 )
    {
      if ( score + delta >= -200 )
        score += delta;
      else
        return -200;
    }
  }
  else if ( score + delta <= 200 )
  {
    score += delta;
  }
  else
  {
    return 200;
  }
  return score;
}

