  int targetDamageProduct; // r27
  unsigned __int16 attackerMaxHp; // r29
  int attackerHalfHp; // r28
  int ratioWeight; // r3
  int score; // r28

  targetMaxHp = fightOutPokemonMaxHpWaruValue(target, 1u);
  targetDamageProduct = (unsigned __int16)(targetMaxHp
                                         * battleAiEstimateMoveDamageAgainstCombatant(
                                             trainer,
                                             attacker,
                                             moveId,
                                             target,
                                             1u)
                                         / 100);
  attackerMaxHp = fightOutPokemonMaxHpWaruValue(attacker, 1u);
  attackerHalfHp = (unsigned __int16)fightOutPokemonNowHpWaruValue(attacker, 2u);
  ratioWeight = battleTrainerGetAttribute(nullptr, 0x27Du, 0x3Eu, 0);
  score = battleAIAddValue(
            0,
            (targetDamageProduct / (unsigned __int16)(attackerMaxHp * attackerHalfHp / 100) - 1) * ratioWeight);
  if ( (unsigned __int8)battleAIGetCombatantEvasionStage(trainer, target) <= 5u )
    return battleAIAddValueByScoreRuleId(score, trainer, 0x27Eu);
